namespace ChessGame.Models
{
    public class BoardState
    {
        public const int Size = 8;
        public Piece[,] Squares { get; } = new Piece[Size, Size];
        public PieceColor CurrentTurn { get; set; } = PieceColor.White;
        public List<Move> MoveHistory { get; } = new();

        public BoardState() => InitializeBoard();

        private void InitializeBoard()
        {
            for (int r = 0; r < Size; r++)
                for (int c = 0; c < Size; c++)
                    Squares[r, c] = Piece.Empty;

            var back = new[] { PieceType.Rook, PieceType.Knight, PieceType.Bishop, PieceType.Queen,
                               PieceType.King, PieceType.Bishop, PieceType.Knight, PieceType.Rook };
            for (int c = 0; c < Size; c++)
            {
                Squares[0, c] = new Piece(back[c], PieceColor.Black);
                Squares[1, c] = new Piece(PieceType.Pawn, PieceColor.Black);
                Squares[6, c] = new Piece(PieceType.Pawn, PieceColor.White);
                Squares[7, c] = new Piece(back[c], PieceColor.White);
            }
        }

        public Piece GetPiece(int r, int c) =>
            r >= 0 && r < Size && c >= 0 && c < Size ? Squares[r, c] : Piece.Empty;

        public void SetPiece(int r, int c, Piece p) => Squares[r, c] = p;
    }
}
