    public class MainViewModel : INotifyPropertyChanged
    {
        private readonly BoardState _board = new();
        public ObservableCollection<SquareVm> Squares { get; } = new();
        private SquareVm? _selected;
        public SquareVm? SelectedSquare { get => _selected; set { _selected = value; OnPropertyChanged(); UpdateHighlights(); } }
        private string _status = "Ход белых";
        public string StatusText { get => _status; set { _status = value; OnPropertyChanged(); } }
        public ICommand SquareClickCommand { get; }

        public MainViewModel()
        {
            SquareClickCommand = new RelayCommand(OnSquareClick);
            for (int r = 0; r < 8; r++)
                for (int c = 0; c < 8; c++)
                    Squares.Add(new SquareVm(r, c, _board.GetPiece(r, c)));
        }

        private void OnSquareClick(object? param)
        {
            if (param is not SquareVm sq) return;
            if (_selected == null)
            {
                var p = _board.GetPiece(sq.Row, sq.Col);
                if (!p.IsEmpty && p.Color == _board.CurrentTurn) SelectedSquare = sq;
                return;
            }
            var moves = MoveGenerator.GetLegalMoves(_board, _selected.Row, _selected.Col);
            var move = moves.FirstOrDefault(m => m.ToRow == sq.Row && m.ToCol == sq.Col);
            if (move.MovedPiece.Type != PieceType.None)
            {
                _board.SetPiece(move.ToRow, move.ToCol, move.MovedPiece);
                _board.SetPiece(move.FromRow, move.FromCol, Piece.Empty);
                _board.MoveHistory.Add(move);
                _board.CurrentTurn = _board.CurrentTurn == PieceColor.White ? PieceColor.Black : PieceColor.White;
                StatusText = _board.CurrentTurn == PieceColor.White ? "Ход белых" : "Ход чёрных";
                foreach (var s in Squares) s.Piece = _board.GetPiece(s.Row, s.Col);
                SelectedSquare = null;
            }
            else
            {
                var p = _board.GetPiece(sq.Row, sq.Col);
                SelectedSquare = (!p.IsEmpty && p.Color == _board.CurrentTurn) ? sq : null;
            }
        }

        private void UpdateHighlights()
        {
            foreach (var s in Squares) { s.IsSelected = s == _selected; s.IsHighlighted = false; }
            if (_selected != null)
                foreach (var m in MoveGenerator.GetLegalMoves(_board, _selected.Row, _selected.Col))
                    Squares.First(s => s.Row == m.ToRow && s.Col == m.ToCol).IsHighlighted = true;
        }

        public event PropertyChangedEventHandler? PropertyChanged;
        protected void OnPropertyChanged([CallerMemberName] string? n = null) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(n));
    }

    public class SquareVm : INotifyPropertyChanged
    {
        public int Row { get; }
        public int Col { get; }
        public bool IsDark => (Row + Col) % 2 == 1;
        private Piece _piece;
        public Piece Piece { get => _piece; set { _piece = value; OnPropertyChanged(); OnPropertyChanged(nameof(Symbol)); } }
        private bool _isSelected;
        public bool IsSelected { get => _isSelected; set { _isSelected = value; OnPropertyChanged(); } }
        private bool _isHighlighted;
        public bool IsHighlighted { get => _isHighlighted; set { _isHighlighted = value; OnPropertyChanged(); } }
        public string Symbol => _piece.Type switch
        {
            PieceType.King => _piece.Color == PieceColor.White ? "♔" : "♚",
            PieceType.Queen => _piece.Color == PieceColor.White ? "♕" : "♛",
            PieceType.Rook => _piece.Color == PieceColor.White ? "♖" : "♜",
            PieceType.Bishop => _piece.Color == PieceColor.White ? "♗" : "♝",
            PieceType.Knight => _piece.Color == PieceColor.White ? "♘" : "♞",
            PieceType.Pawn => _piece.Color == PieceColor.White ? "♙" : "♟",
            _ => ""
        };
        public SquareVm(int r, int c, Piece p) { Row = r; Col = c; _piece = p; }
        public event PropertyChangedEventHandler? PropertyChanged;
        protected void OnPropertyChanged([CallerMemberName] string? n = null) => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(n));
    }
}
